static void RemoveComments(char* buffer, const char* start, const char* end)
{
    for (;;) {
        char* s = std::strstr(buffer, start);
        if (!s) return;
        char* e = std::strstr(s + std::strlen(start), end);
        if (!e) { *s = 0; return; }
